class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        if not nums or k == 0:
            return len(nums)

        # Sort the unique elements to group them into ranges easily
        sorted_nums = sorted(list(set(nums)))

        count = 0
        current_range_end = sorted_nums[0] - k

        for num in sorted_nums:
            # The range of values a number 'num' can take after adding an integer in [-k, k] is [num - k, num + k].
            # We want to greedily extend the current range's end to include the current number.
            # The maximum value we can reach from the current range's end by adding k is current_range_end + k.
            # If num <= current_range_end + k, then num can be extended to match current_range_end + k (or beyond).
            # So we can extend the current range's end to max(current_range_end + k, num + k).

            if num <= current_range_end + k:
                # We can extend the current range's end to include this number and possibly more numbers.
                # The new end will be max(current_range_end + k, num + k)
                current_range_end = max(current_range_end + k, num + k)
                count += 1
            else:
                # This number cannot be extended to match the previous range's end.
                # Start a new range starting from this number's range.
                current_range_end = num + k
                count += 1

        return count

    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        if not nums or k == 0:
            return len(nums)

        sorted_nums = sorted(list(set(nums)))

        count = 0
        current_range_end = sorted_nums[0] - k

        for num in sorted_nums:
            if num <= current_range_end + k:
                current_range_end = max(current_range_end + k, num + k)
                count += 1
            else:
                current_range_end = num + k
                count += 1

        return count
